import subprocess

# Debug with detailed tracing
code = r'''
from boltons.iterutils import remap, default_enter, default_exit, default_visit

inner = {'x': 1}
print("inner id:", id(inner))

# Custom enter that prints what's happening
def debug_enter(path, key, value):
    print(f"ENTER path={path}, key={key}, value={value!r}, id={id(value)}")
    return default_enter(path, key, value)

def debug_exit(path, key, old_parent, new_parent, new_items):
    print(f"EXIT path={path}, key={key}")
    return default_exit(path, key, old_parent, new_parent, new_items)

try:
    out = remap([inner, inner], cache=False, enter=debug_enter, exit=debug_exit)
    print("out:", out)
except RecursionError as e:
    print("RecursionError:", e)
'''
result = subprocess.run(['python', '-c', code], capture_output=True, text=True, timeout=5)
print(result.stdout)
if result.stderr:
    print("STDERR:", result.stderr[-300:])
